# frozen_string_literal: true

require "json"
require "securerandom"
require "fileutils"

module Merlin
  # Audio files imported from this Mac, kept per speaker and merged into the
  # server's playlist at every sync (the speaker's hierarchy is regenerated by
  # Merlin each time, so local additions must be re-inserted).
  #
  # The speaker's tree is section -> folder -> track (e.g. Histoires -> Les
  # Belles Histoires -> episode). Tracks go into an existing folder or a local
  # folder created inside a section; each node needs a <uuid>.jpg cover and each
  # track a <uuid>.mp3.
  class LocalLibrary
    FALLBACK_FOLDER = "Mes fichiers"
    TITLE_BYTES = 63 # longest title the server sends; it shortens with "..."

    Entry = Data.define(:uuid, :kind, :title, :parent, :added_at, :duration, :source) do
      def folder? = kind == "folder"
      def track? = kind == "track"
      def to_h = super.transform_keys(&:to_s)
    end

    attr_reader :dir

    def initialize(dir:, setting_id:, media: Media)
      @dir = dir
      @path = File.join(dir, "#{setting_id}.json")
      @media = media
      load
    end

    def entries = @entries.dup
    def folders = @entries.select(&:folder?)
    def tracks = @entries.select(&:track?)
    def find(uuid) = @entries.find { _1.uuid == uuid }
    def children(parent) = @entries.select { _1.parent == parent }
    def empty? = @entries.empty?

    def audio_path(uuid) = File.join(files_dir, "#{uuid}.mp3")
    def cover_path(uuid) = File.join(files_dir, "#{uuid}.jpg")

    # A new folder inside one of the speaker's sections.
    def add_folder(title, parent:)
      entry = Entry.new(uuid: SecureRandom.uuid, kind: "folder", title: self.class.speaker_title(title),
                        parent: parent, added_at: Time.now.to_i, duration: nil, source: nil)
      @media.default_cover(cover_path(entry.uuid))
      @entries << entry
      save
      entry
    end

    # Imports one audio file into parent (a speaker folder or a local folder).
    # Returns [entry, :copied | :transcoded].
    def import(path, parent:, title: nil)
      info = @media.probe(path)
      FileUtils.mkdir_p(files_dir)
      uuid = SecureRandom.uuid
      action = @media.prepare_audio(path, audio_path(uuid), info)
      @media.prepare_cover(path, cover_path(uuid), info)
      name = title || info.title || File.basename(path, ".*").tr("_", " ")
      entry = Entry.new(uuid: uuid, kind: "track", title: self.class.speaker_title(name), parent: parent,
                        added_at: Time.now.to_i, duration: info.duration, source: File.basename(path))
      @entries << entry
      save
      [entry, action]
    rescue StandardError
      FileUtils.rm_f([audio_path(uuid), cover_path(uuid)]) if uuid
      raise
    end

    def rename(uuid, title)
      replace(uuid) { _1.with(title: self.class.speaker_title(title)) }
    end

    def move(uuid, parent)
      replace(uuid) { _1.with(parent: parent) }
    end

    # Removing a folder removes the tracks in it.
    def remove(uuid)
      doomed = [uuid] + children(uuid).map(&:uuid)
      doomed.each { |u| FileUtils.rm_f([audio_path(u), cover_path(u)]) }
      @entries.reject! { doomed.include?(_1.uuid) }
      save
    end

    # Inserts local folders/tracks into plan["playlistText"] and adds their
    # files to plan["fileList"] (with a local "path", so nothing is
    # downloaded). Tracks whose folder no longer exists on the speaker go to a
    # "Mes fichiers" folder in the first section. Returns a summary.
    def merge!(plan)
      return { tracks: 0, folders: 0, relocated: [] } if empty?

      tree = JSON.parse(plan.fetch("playlistText"))
      containers = {}
      index = lambda do |nodes|
        nodes.each do |n|
          next unless n["child"].is_a?(Array)

          containers[n["uuid"]] = n
          index.call(n["child"])
        end
      end
      index.call(tree)
      sections = tree.select { _1["child"].is_a?(Array) && !_1.key?("favorite") }
      raise Error, "the speaker playlist has no section to add files to" if sections.empty?

      files = []
      folders.each do |f|
        parent = containers[f.parent] || sections.first
        node = { "uuid" => f.uuid, "title" => f.title, "child" => [] }
        parent["child"] << node
        containers[f.uuid] = node
        files << file_entry(f, "image")
      end

      relocated = []
      tracks.each do |t|
        parent = containers[t.parent]
        unless parent
          relocated << t.title
          parent = fallback_folder(sections.first, containers, files)
        end
        parent["child"] <<{ "uuid" => t.uuid, "title" => t.title, "add_time" => t.added_at, "limit_time" => 0,
                             "type" => "free" }
        files << file_entry(t, "image") << file_entry(t, "audio")
      end

      plan["playlistText"] = JSON.generate(tree)
      plan["fileList"] = Array(plan["fileList"]) + files
      { tracks: tracks.size, folders: folders.size, relocated: relocated }
    end

    # Titles as the speaker gets them from the server: at most 63 bytes,
    # longer ones shortened to 60 bytes + "...".
    def self.speaker_title(title)
      t = title.to_s.strip.gsub(/\s+/, " ")
      raise ArgumentError, "title can't be empty" if t.empty?
      return t if t.bytesize <= TITLE_BYTES

      "#{t.byteslice(0, 60).scrub('').rstrip}..."
    end

    # Expands folders into the audio files they contain (sorted), keeps files.
    def self.audio_files(paths)
      paths.flat_map do |p|
        p = File.expand_path(p)
        if File.directory?(p)
          Dir.glob(File.join(p, "**", "*")).select { Media::AUDIO_EXTENSIONS.include?(File.extname(_1).downcase) }.sort
        elsif File.file?(p)
          [p]
        else
          raise Error, "no such file: #{p}"
        end
      end
    end

    private

    def files_dir = File.join(dir, "files")

    def file_entry(entry, type)
      path = type == "audio" ? audio_path(entry.uuid) : cover_path(entry.uuid)
      { "type" => type, "filename" => File.basename(path), "title" => entry.title, "path" => path }
    end

    def fallback_folder(section, containers, files)
      unless @meta["fallback_uuid"]
        @meta["fallback_uuid"] = SecureRandom.uuid
        save
      end
      uuid = @meta["fallback_uuid"]
      containers[uuid] ||= begin
        @media.default_cover(cover_path(uuid)) unless File.exist?(cover_path(uuid))
        node = { "uuid" => uuid, "title" => FALLBACK_FOLDER, "child" => [] }
        section["child"] << node
        files << { "type" => "image", "filename" => "#{uuid}.jpg", "title" => FALLBACK_FOLDER, "path" => cover_path(uuid) }
        node
      end
    end

    def replace(uuid)
      i = @entries.index { _1.uuid == uuid } or raise Error, "unknown item #{uuid}"
      @entries[i] = yield(@entries[i])
      save
      @entries[i]
    end

    def load
      data = File.exist?(@path) ? JSON.parse(File.read(@path)) : {}
      @meta = data.fetch("meta", {})
      @entries = Array(data["entries"]).map { |h| Entry.new(**h.transform_keys(&:to_sym)) }
    end

    def save
      FileUtils.mkdir_p(dir)
      File.write(@path, JSON.pretty_generate("meta" => @meta, "entries" => @entries.map(&:to_h)))
    end
  end
end
